<?php use App\Domain\Deliveries\DeliveryRules as Rules; $d=$delivery;$selectedAction=$selectedAction??'';?>
<div class="deliveries-editor deliveries-detail"><section class="admin-page-head"><div><p class="admin-kicker">ENTREGA · <?= e(Rules::LABELS[$d['status']]) ?></p><h1><?= e($d['folio']) ?></h1><p><?= e($d['customer_name'].' · '.$d['branch_name']) ?></p></div><a class="admin-secondary-button" data-admin-modal-cancel href="/admin/deliveries">Entregas</a></section>
<section class="admin-panel deliveries-summary"><header><h2>Entrega acordada</h2><span class="deliveries-status" data-state="<?= e($d['status']) ?>"><?= e(Rules::LABELS[$d['status']]) ?></span></header><dl><div><dt>Cliente</dt><dd><?= e($d['customer_name']) ?></dd></div><div><dt>Sucursal</dt><dd><?= e($d['branch_name']) ?></dd></div><div><dt>Cotización relacionada</dt><dd><?= e($d['quote_folio'].' · versión '.$d['version_number']) ?></dd></div><div><dt>Modalidad</dt><dd><?= $d['mode']==='pickup'?'Recolección en sucursal':'Entrega a domicilio' ?></dd></div><div><dt>Fecha acordada</dt><dd><?= e($d['scheduled_date']) ?></dd></div><div><dt>Responsable</dt><dd><?= e($d['actor_name']) ?></dd></div><div><dt>Costo acordado</dt><dd><?= e('$'.$d['delivery_cost'].' MXN') ?></dd></div><div><dt>Receptor acordado</dt><dd><?= e($d['receiver']?:'Por confirmar') ?></dd></div><?php if($d['address']):?><div class="deliveries-field-full"><dt>Dirección acordada</dt><dd><?= e($d['address']) ?></dd></div><?php endif?><?php if($d['location_reference']):?><div class="deliveries-field-full"><dt>Referencia de ubicación</dt><dd><?= e($d['location_reference']) ?></dd></div><?php endif?><?php if($stop):?><div class="deliveries-field-full"><dt>Ruta y parada</dt><dd><?= e($stop['run_name'].' · parada '.$stop['position'].' · ruta #'.$stop['run_id'].' · vehículo #'.$stop['vehicle_id'].' · repartidor #'.$stop['driver_id']) ?></dd></div><?php endif?></dl><p class="deliveries-note">Preparar no altera inventario. La salida física consume el apartado una sola vez; confirmar la recepción conserva ese movimiento.</p></section>
<section class="admin-panel admin-table-panel deliveries-directory"><header class="deliveries-directory-heading"><div><h2>Mercancía de la entrega</h2><p>Consulta las cantidades asignadas, despachadas y recibidas.</p></div></header><div class="admin-table-wrap" tabindex="0" role="region" aria-label="Cantidades de la entrega"><table class="admin-table"><thead><tr><th>Mercancía</th><th>Asignada</th><th>Preparada</th><th>Despachada</th><th>Recibida</th><th>Pendiente cliente</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td data-label="Mercancía"><?= e($i['sku'].' · '.$i['description'].' · '.$i['symbol']) ?></td><?php foreach(['quantity'=>'Asignada','prepared_quantity'=>'Preparada','dispatched_quantity'=>'Despachada','received_quantity'=>'Recibida']as $key=>$label):?><td data-label="<?= e($label) ?>"><?= e($i[$key]) ?></td><?php endforeach?><td data-label="Pendiente cliente"><?= e($i['pending_quantity']) ?></td></tr><?php endforeach?></tbody></table></div></section>
<section class="admin-panel deliveries-pending"><h2>Pendiente de la cotización</h2><?php foreach($pending as $i):?><p><?= e($i['sku']) ?> · Documentado <?= e($i['quantity']) ?> · Despachado <?= e($i['dispatched_quantity']) ?> · Recibido <?= e($i['received_quantity']) ?> · Pendiente <?= e($i['pending_quantity']) ?> · Sin asignar <?= e($i['unallocated_quantity']) ?></p><?php endforeach?></section>
<?php foreach(Rules::ACTIONS as $action=>$label):if(!$actions[$action])continue;try{Rules::transition($d['status'],$action);}catch(Throwable){continue;}?>
<?php if($selectedAction!==$action):?><a class="deliveries-action-link" data-admin-form-link href="/admin/deliveries/detail?id=<?= e($d['id']) ?>&amp;action=<?= e($action) ?>"><strong><?= e($label) ?></strong><span aria-hidden="true">→</span></a><?php continue;endif?><section class="admin-panel deliveries-action-panel"><div class="admin-panel-head"><h2><?= e($label) ?></h2><a class="deliveries-text-link" data-admin-form-link href="/admin/deliveries/detail?id=<?= e($d['id']) ?>">Volver al detalle</a></div><form method="post" action="/admin/deliveries/action" class="admin-form" data-delivery-event>
<input type="hidden" name="_token" value="<?= e($csrf) ?>"><input type="hidden" name="id" value="<?= e($d['id']) ?>"><input type="hidden" name="lock_version" value="<?= e($d['lock_version']) ?>"><input type="hidden" name="operation_key" value="<?= e(bin2hex(random_bytes(20))) ?>"><input type="hidden" name="action" value="<?= e($action) ?>">
<?php if(in_array($action,['edit','confirm'],true)):?><div class="admin-form-grid"><?php foreach($items as $i):$max=$action==='edit'?$i['quantity']:$i['pending_receipt'];?><label class="admin-field"><span><?= e($i['sku'].' · '.$i['symbol']) ?> · <?= e($action==='edit'?'Actual':'Pendiente') ?> <?= e($max) ?></span><input name="quantity[<?= e($i['id']) ?>]" inputmode="decimal" value="<?= e($action==='edit'?$max:'0') ?>"></label><?php endforeach?></div><?php endif?>
<?php if($action==='confirm'):?><label class="admin-field"><span>Nombre de quien recibió</span><input name="receiver" maxlength="120" required></label><?php endif?>
<?php if($action==='assign'&&$d['mode']==='home'):?><p>Selecciona una ruta de la misma sucursal y fecha. <a class="deliveries-text-link" data-admin-form-link href="/admin/deliveries/resources?kind=delivery_runs">Consultar rutas</a></p><div class="admin-form-grid"><label class="admin-field"><span>ID de ruta</span><input name="run_id" inputmode="numeric" required></label><label class="admin-field"><span>Posición de parada</span><input name="position" inputmode="numeric" required></label></div><?php endif?>
<label class="admin-field"><span>Observaciones <?= in_array($action,['cancel','incident','retry'],true)?'(obligatorias)':'' ?></span><textarea name="notes" maxlength="500" <?= in_array($action,['cancel','incident','retry'],true)?'required minlength="5"':'' ?>></textarea></label>
<?php if(in_array($action,['dispatch','confirm','cancel'],true)):?><label class="deliveries-confirm"><input type="checkbox" name="physical_confirmation" value="1" required> <?= e($action==='dispatch'?'Confirmo que toda la mercancía preparada sale físicamente.':($action==='confirm'?'Confirmo las cantidades recibidas por el cliente.':'Confirmo la cancelación sin salida física.')) ?></label><?php endif?><button class="admin-primary-button"><?= e($label) ?></button></form></section><?php endforeach?>
<?php if($history):?><section class="admin-panel deliveries-history"><h2>Historial de la entrega</h2><ol><?php foreach($history as $h):?><li><strong><?= e((Rules::ACTIONS+['create'=>'Entrega creada'])[$h['action']]??$h['action']) ?></strong> · <?= e($h['actor_name']) ?> · <?= e($h['created_at']) ?> UTC · <?= e(Rules::LABELS[$h['to_status']]??$h['to_status']) ?><p><?= e($h['notes']) ?> <?= e($h['quantity']??'') ?><?php if($h['inventory_movement_id']):?> · Movimiento de inventario #<?= e($h['inventory_movement_id']) ?><?php endif?><?php if($h['receiver']):?> · Recibió <?= e($h['receiver']) ?><?php endif?></p><?php if(($canEvidence??false)&&in_array($h['action'],['confirm','incident'],true)):?><a href="/admin/media?kind=evidence&amp;parent_id=<?= e($h['id']) ?>">Fotografías de esta operación</a><?php endif?></li><?php endforeach?></ol></section><?php endif?>
<section class="admin-panel"><p>Un intento fallido conserva la mercancía despachada pendiente de recepción. Para retornos o pérdidas se requiere un procedimiento físico aprobado; cambiar el estado no reintegra stock. Las fotografías se consultan desde cada confirmación o incidencia autorizada.</p></section>

